   // the breastplate opens with each phase. There is nothing inside
   if(ph>=2){const k=ph>=3?1:.6;c.fillStyle=VOID;c.beginPath();c.moveTo(0,sy+h*.04);c.lineTo(w*.14*k,sy+h*.12);c.lineTo(w*.06*k,sy+h*.3);c.lineTo(-w*.08*k,sy+h*.28);c.lineTo(-w*.14*k,sy+h*.1);c.closePath();c.fill();c.strokeStyle=V;c.lineWidth=2;c.stroke();glow(c,0,sy+h*.16,30*k+8*Math.sin(t*3),V,.95)}else{c.fillStyle=hexA(VD,.8);c.beginPath();c.arc(0,sy+h*.14,7,0,TAU);c.fill()}c.restore();
  // the left arm, resting on the sword or the air
