 function oath(m,X,n){const b=X.box(),f=X.fl();m.oath=26;m.frozenAI=1;m.shield=m.mhp*9;m.shield0=m.shield;m.vx=0;m.pil=[];X.burst(m.x,m.y+m.h/2,[V,'#04020a'],22,260);m.x=m.thr||(b.l+b.r)/2;m.st='idle';m.atk=null;m.bt=2.4;X.burst(m.x,m.y+m.h/2,[V,SL],22,260);DG.music.sfx('choir',.8);X.say('THE OATH OF STONE','Break the pillars. Nothing else can touch him',2400);const W2=(b.r-b.l)/(n+1);for(let i=0;i<n;i++){let x=b.l+W2*(i+1)+rn(-T,T);if(Math.abs(x-m.x)<T*4)x+=(x<m.x?-1:1)*T*4;x=X.clX(x);const q=X.spawn('king_pillar',x,f,{summon:true});if(q)m.pil.push(q)}}
